let cleaningGroupData=null,selectedCleaningGroup=0,cleaningGroupLoading=false;
async function cleaningGroupRequest(action='',data){return api('/api/cleaning-groups'+action,data);}
async function renderCleaningGroups(target){if(cleaningGroupLoading)return;cleaningGroupLoading=true;try{const d=await cleaningGroupRequest();if(location.hash!=='#cleaning')return;cleaningGroupData=d;const g=d.groups.find(x=>x.id===selectedCleaningGroup)||d.groups[0];selectedCleaningGroup=g?.id||0;target.innerHTML=`<h1 class="view-title">청소 당번</h1><p class="muted">가입한 청소 그룹별로 당번과 공용 공간을 관리하세요. 여러 부서가 같은 그룹에 참여할 수 있습니다.</p><div class="toolbar cleaning-group-toolbar"><label>내 청소 그룹<select class="field" id="cleaning-group-select">${d.groups.map(x=>`<option value="${x.id}" ${x.id===selectedCleaningGroup?'selected':''}>${esc(x.name)}${x.manage?' · 관리':''}</option>`).join('')}</select></label>${d.admin?'<button type="button" class="primary" id="cleaning-group-create">＋ 그룹 만들기</button>':''}</div>${g?`<section class="panel"><h2>${esc(g.name)} · 이번 주 담당자</h2><p class="muted">${d.week} 시작 주 · ${g.jobs.filter(x=>x.done).length}/${g.jobs.length}명 완료</p>${g.jobs.map(j=>`<div class="row"><span><strong>${esc(j.name)}</strong> · ${esc(j.area)}</span><small>${j.done?'완료':'예정'}</small>${!j.done&&(g.manage||j.user_id===hfAuth.user.id)?`<button class="primary" data-cg-action="complete" data-job="${j.id}">청소 완료</button>`:''}${g.manage?`<button class="task-delete" data-cg-action="remove-job" data-job="${j.id}">배정 삭제</button>`:''}</div>`).join('')||'<p class="muted">이번 주 배정이 없습니다.</p>'}${g.manage?`<details class="cleaning-settings"><summary>담당자 직접 배정</summary><form id="cg-assign" class="board-form"><label>담당자<select class="field" name="user_id">${g.members.map(m=>`<option value="${m.id}">${esc(m.name)}</option>`).join('')}</select></label><label>구역<input class="field" name="area" maxlength="80" required></label><button class="primary" ${g.members.length?'':'disabled'}>배정 추가</button><p role="status"></p></form></details>`:''}</section><section class="panel"><h2>주간 로테이션</h2><p class="muted">${esc(g.area)} · ${g.start_week} 시작</p><ol class="cleaning-rotation-order">${g.rotation.map((id,i)=>`<li><span>${i+1}</span>${esc(g.members.find(m=>m.id===id)?.name||'참여 종료 회원')}</li>`).join('')||'<li>자동 배정 중지 상태</li>'}</ol>${g.manage?`<details class="cleaning-settings"><summary>로테이션 설정 변경</summary><form id="cg-rotation" class="board-form"><div class="cleaning-form-fields"><label>시작 주<input class="field" name="start_week" type="date" min="${d.week}" value="${g.start_week>=d.week?g.start_week:d.week}" required></label><label>담당 구역<input class="field" name="area" value="${esc(g.area)}" maxlength="80" required></label></div><p class="muted">그룹 회원의 순서를 입력하세요. 빈칸은 로테이션 제외입니다. 이미 배정된 이번 주 당번은 유지됩니다.</p><div class="cleaning-order-grid">${g.members.map(m=>`<label class="cleaning-order-field"><span>${esc(m.name)}</span><input class="field" data-cg-order="${m.id}" type="number" min="1" max="100" placeholder="제외" value="${g.rotation.includes(m.id)?g.rotation.indexOf(m.id)+1:''}"></label>`).join('')}</div><button class="primary">순서 저장</button><p role="status"></p></form></details>`:''}</section><section class="panel"><div class="task-list-heading"><h2>그룹 회원 ${g.members.length}명</h2>${g.manage?'<button type="button" class="task-edit-save" id="cg-invite-open">회원 초대</button>':''}</div>${g.members.map(m=>`<div class="row"><span>${esc(m.name)} ${m.manager?'<small>그룹 관리자</small>':''}</span>${d.admin?`<button class="task-edit-save" data-cg-manager="${m.id}" data-enabled="${!m.manager}">${m.manager?'관리자 해제':'관리자 지정'}</button>`:''}${g.manage&&m.id!==hfAuth.user.id&&(d.admin||!m.manager)?`<button class="task-delete" data-cg-remove-member="${m.id}">그룹 제외</button>`:''}</div>`).join('')}</section>`:'<section class="panel"><h2>가입한 청소 그룹이 없습니다.</h2><p>그룹 관리자의 초대를 받은 뒤 알림에서 수락해 주세요.</p></section>'}<p id="cg-status" role="status" class="muted"></p>`;}catch(e){if(location.hash==='#cleaning')target.innerHTML='<h1 class="view-title">청소 당번</h1><p role="alert">'+esc(e.message)+'</p>';}finally{cleaningGroupLoading=false;}}
document.addEventListener('change',e=>{if(e.target.id==='cleaning-group-select'){selectedCleaningGroup=Number(e.target.value);renderCleaningGroups(document.querySelector('#content'));}});
document.addEventListener('click',async e=>{const b=e.target.closest('#cleaning-group-create,#cg-invite-open,[data-cg-action],[data-cg-manager],[data-cg-remove-member]');if(!b)return;const g=cleaningGroupData?.groups.find(x=>x.id===selectedCleaningGroup);if(b.id==='cleaning-group-create'){extraDialog('청소 그룹 만들기','<form class="board-form" id="cg-create"><label>그룹 이름<input class="field" name="name" maxlength="80" placeholder="예: 5층 공용 공간" required></label><p class="muted">생성 후 회원을 초대하고, 그룹 관리자와 로테이션을 설정하세요.</p><button class="primary">그룹 만들기</button><p role="status"></p></form>');return;}if(b.id==='cg-invite-open'){extraDialog('청소 그룹 회원 초대',`<form id="cg-invite" class="board-form"><p>${esc(g.name)} · 초대 수락 후 가입됩니다.</p><div class="meal-member-list">${g.invitees.map(m=>`<label class="meal-member"><input type="checkbox" name="recipients" value="${m.id}">${esc(m.name)}</label>`).join('')||'<p>초대할 회원이 없습니다.</p>'}</div><button class="primary" ${g.invitees.length?'':'disabled'}>회원 초대</button><p role="status"></p></form>`);return;}let action=b.dataset.cgAction,data={group_id:g.id,job_id:Number(b.dataset.job)};if(b.hasAttribute('data-cg-manager')){action='manager';data.user_id=Number(b.dataset.cgManager);data.manager=b.dataset.enabled==='true';}if(b.hasAttribute('data-cg-remove-member')){if(!confirm('이 회원을 그룹과 향후 로테이션에서 제외할까요? 기존 청소 기록은 유지됩니다.'))return;action='remove-member';data.user_id=Number(b.dataset.cgRemoveMember);}if(action==='remove-job'&&!confirm('이번 주 배정을 삭제할까요?'))return;b.disabled=true;try{await cleaningGroupRequest('/'+action,data);await renderCleaningGroups(document.querySelector('#content'));await loadActivity();}catch(error){b.disabled=false;document.querySelector('#cg-status').textContent=error.message;}});
document.addEventListener('submit',async e=>{const f=e.target;if(!['cg-create','cg-invite','cg-rotation','cg-assign'].includes(f.id))return;e.preventDefault();const fd=new FormData(f),action=f.id.slice(3),data={...Object.fromEntries(fd),group_id:selectedCleaningGroup},b=f.querySelector('button');if(action==='invite')data.recipients=fd.getAll('recipients').map(Number);if(action==='assign')data.user_id=Number(data.user_id);if(action==='rotation'){const order=[...f.querySelectorAll('[data-cg-order]')].filter(i=>i.value!=='').map(i=>({id:Number(i.dataset.cgOrder),order:Number(i.value)}));if(order.some(x=>!Number.isInteger(x.order)||x.order<1)||new Set(order.map(x=>x.order)).size!==order.length){f.querySelector('[role=status]').textContent='참여 순서를 중복 없이 입력해 주세요.';return;}data.members=order.sort((a,b)=>a.order-b.order).map(x=>x.id);}b.disabled=true;try{const r=await cleaningGroupRequest('/'+action,data);if(action==='create')selectedCleaningGroup=r.id;if(action==='invite'){f.querySelector('[role=status]').textContent='초대를 보냈습니다. 받은 회원의 알림에 표시됩니다.';b.disabled=false;return;}f.closest('dialog')?.close();await renderCleaningGroups(document.querySelector('#content'));await loadActivity();}catch(error){b.disabled=false;f.querySelector('[role=status]').textContent=error.message;}});

